"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[27504],{3331:(a,e,i)=>{i.d(e,{R:()=>t,x:()=>s});var o=i(36672);const n={},r=o.createContext(n);function t(a){const e=o.useContext(r);return o.useMemo((function(){return"function"==typeof a?a(e):{...e,...a}}),[e,a])}function s(a){let e;return e=a.disableParentContext?"function"==typeof a.components?a.components(n):a.components||n:t(a.components),o.createElement(r.Provider,{value:e},a.children)}},41012:(a,e,i)=>{i.r(e),i.d(e,{assets:()=>c,contentTitle:()=>s,default:()=>d,frontMatter:()=>t,metadata:()=>o,toc:()=>w});const o=JSON.parse('{"id":"2023/03/31","title":"31","description":"March 31, 2023","source":"@site/i18n/pl/docusaurus-plugin-content-docs/current/2023/03/31.md","sourceDirName":"2023/03","slug":"/2023/03/31","permalink":"/pl/2023/03/31","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/pl/docusaurus-plugin-content-docs//current/2023/03/31.md","tags":[],"version":"current","frontMatter":{"localized_date":"31 marca 2023","top_news":"US Ban Bill Raises Concerns for VPNs & TikTok"},"sidebar":"defaultSidebar","previous":{"title":"01","permalink":"/pl/2023/04/01"},"next":{"title":"30","permalink":"/pl/2023/03/30"}}');var n=i(23420),r=i(3331);const t={localized_date:"31 marca 2023",top_news:"US Ban Bill Raises Concerns for VPNs & TikTok"},s=void 0,c={},w=[{value:"March 31, 2023",id:"march-31-2023",level:2},{value:"US Ban Bill Raises Concerns for VPNs &amp; TikTok",id:"us-ban-bill-raises-concerns-for-vpns--tiktok",level:2},{value:"Mieszane opinie na temat warto\u015bci Y Combinatora dla startup\xf3w",id:"mieszane-opinie-na-temat-warto\u015bci-y-combinatora-dla-startup\xf3w",level:2},{value:"Scratch: Popularny wizualny j\u0119zyk programowania dla dzieci",id:"scratch-popularny-wizualny-j\u0119zyk-programowania-dla-dzieci",level:2},{value:"Wyzwania i kompromisy w technologii o\u015bwietlenia LED",id:"wyzwania-i-kompromisy-w-technologii-o\u015bwietlenia-led",level:2},{value:"Ponad po\u0142owa nowych pakiet\xf3w NPM to spam",id:"ponad-po\u0142owa-nowych-pakiet\xf3w-npm-to-spam",level:2},{value:"US proponuje ustawy zagra\u017caj\u0105ce wolno\u015bci i prywatno\u015bci w technice",id:"us-proponuje-ustawy-zagra\u017caj\u0105ce-wolno\u015bci-i-prywatno\u015bci-w-technice",level:2},{value:"Open-Source 3D Rendering Engine for Education &amp; Integration",id:"open-source-3d-rendering-engine-for-education--integration",level:2},{value:"Google zaprzecza, \u017ce u\u017cywa\u0142 OpenAI&#39;s ChatGPT do szkolenia Barda",id:"google-zaprzecza-\u017ce-u\u017cywa\u0142-openais-chatgpt-do-szkolenia-barda",level:2},{value:"Twitter API Neglected, User Dissatisfaction Grows",id:"twitter-api-neglected-user-dissatisfaction-grows",level:2},{value:"San Jose Police Union Director Charged with Drug Smuggling",id:"san-jose-police-union-director-charged-with-drug-smuggling",level:2}];function z(a){const e={a:"a",h2:"h2",p:"p",...(0,r.R)(),...a.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(e.h2,{id:"march-31-2023",children:"March 31, 2023"}),"\n",(0,n.jsx)(e.h2,{id:"us-ban-bill-raises-concerns-for-vpns--tiktok",children:"US Ban Bill Raises Concerns for VPNs & TikTok"}),"\n",(0,n.jsxs)(e.p,{children:["US ban bill supported by the White House and aimed at regulating the internet could make VPNs illegal, grant fines up to $1M and 20 years of imprisonment, and be viewed as an attack on civil liberties. Projekt ustawy ma poparcie obu stron, skupia si\u0119 na obawach o bezpiecze\u0144stwo narodowe zwi\u0105zane z Chinami i ograniczaniu transakcji biznesowych z tym krajem. UE mo\u017ce nie pod\u0105\u017ca\u0107 za trendem USA, poniewa\u017c kraje maj\u0105 w\u0142asn\u0105 struktur\u0119 prawn\u0105, a zakaz TikTok mo\u017ce doprowadzi\u0107 do resentymentu w\u015br\xf3d m\u0142odych ludzi i odwetu na rz\u0105d USA. Krytycy zakazu twierdz\u0105, \u017ce zagra\u017ca on prywatno\u015bci jednostki oraz wolno\u015bci s\u0142owa i wypowiedzi.\n",(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35366955",children:"Hacker News Link"}),", ",(0,n.jsx)(e.a,{href:"https://www.youtube.com/watch?v=FWQGA_n5Z4M",children:"Original Post"}),"."]}),"\n",(0,n.jsx)(e.h2,{id:"mieszane-opinie-na-temat-warto\u015bci-y-combinatora-dla-startup\xf3w",children:"Mieszane opinie na temat warto\u015bci Y Combinatora dla startup\xf3w"}),"\n",(0,n.jsxs)(e.p,{children:["Opinie na temat warto\u015bci Y Combinatora (YC) dla startup\xf3w s\u0105 mieszane, w zale\u017cno\u015bci od indywidualnych perspektyw i potrzeb. Podczas gdy niekt\xf3rzy ceni\u0105 sie\u0107 kontakt\xf3w i mentorstwo YC, inni krytykuj\u0105 jego porady i skupienie si\u0119 na kr\xf3tkoterminowych celach. Reputacja i marka YC mo\u017ce pom\xf3c w zbieraniu funduszy, ale nielimitowana umowa SAFE i nacisk na skalowanie za wszelk\u0105 cen\u0119 mog\u0105 nie odpowiada\u0107 wszystkim za\u0142o\u017cycielom. Dyskusyjne jest r\xf3wnie\u017c znaczenie budowania spo\u0142eczno\u015bci i osobistych po\u0142\u0105cze\u0144 w formacie zdalnym. Ostatecznie, warto\u015b\u0107 YC zale\u017cy od zdolno\u015bci za\u0142o\u017cyciela do wykorzystania jego zasob\xf3w, aby zmaksymalizowa\u0107 szanse na sukces.\n",(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35373019",children:"Hacker News Link"}),", ",(0,n.jsx)(e.a,{href:"https://acecreamu.substack.com/p/is-y-combinator-worth-the-money",children:"Original Post"}),"."]}),"\n",(0,n.jsx)(e.h2,{id:"scratch-popularny-wizualny-j\u0119zyk-programowania-dla-dzieci",children:"Scratch: Popularny wizualny j\u0119zyk programowania dla dzieci"}),"\n",(0,n.jsxs)(e.p,{children:["Scratch to popularny wizualny j\u0119zyk programowania skierowany do dzieci, kt\xf3ry wykorzystuje kolorowe bloki zamiast kodowania tekstowego, aby pom\xf3c im w nauce koncepcji programistycznych. Program obejmuje podstawowe zasady programowania, takie jak zmienne, listy, struktury przep\u0142ywu sterowania if/else i p\u0119tle oraz wsp\xf3\u0142bie\u017cno\u015b\u0107 opart\u0105 na zdarzeniach. Scratch ma proste, przyjazne dla u\u017cytkownika podej\u015bcie, kt\xf3re zach\u0119ca dzieci do odkrywania oblicze\u0144 w kreatywny spos\xf3b, a tak\u017ce k\u0142adzie du\u017cy nacisk na interakcj\u0119 z r\xf3wie\u015bnikami i dzielenie si\u0119 prac\u0105 w celu otrzymania informacji zwrotnej. Spo\u0142eczno\u015b\u0107 Scratcha jest jedn\u0105 z najwi\u0119kszych spo\u0142eczno\u015bci koder\xf3w na \u015bwiecie, z ponad 103 milionami u\u017cytkownik\xf3w i 123 milionami projekt\xf3w udost\u0119pnionych na platformie. Chocia\u017c istniej\u0105 obawy dotycz\u0105ce nieuregulowanych sieci medi\xf3w spo\u0142eczno\u015bciowych i dzieci graj\u0105cych w gry wideo zamiast u\u017cywania Scratcha do cel\xf3w edukacyjnych, narz\u0119dzie to zainspirowa\u0142o wielu do zainteresowania si\u0119 programowaniem, z projektami od pocz\u0105tkuj\u0105cych koder\xf3w do zaawansowanych umiej\u0119tno\u015bci programowania.\n",(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35373052",children:"Hacker News Link"}),", ",(0,n.jsx)(e.a,{href:"https://scratch.mit.edu/about",children:"Original Post"}),"."]}),"\n",(0,n.jsx)(e.h2,{id:"wyzwania-i-kompromisy-w-technologii-o\u015bwietlenia-led",children:"Wyzwania i kompromisy w technologii o\u015bwietlenia LED"}),"\n",(0,n.jsxs)(e.p,{children:["\u017bar\xf3wki LED maj\u0105 problemy z szybk\u0105 awari\u0105, s\u0142abym oddawaniem barw i wska\u017anikami podobie\u0144stwa widmowego, \u017ale zaprojektowanymi zasilaczami, przegrzewaniem i wy\u017cszym kosztem dla o\u015bwietlenia wewn\u0119trznego. Dla o\u015bwietlenia LED niezb\u0119dne s\u0105 zasilacze sta\u0142opr\u0105dowe, a oprawy musz\u0105 by\u0107 zaprojektowane inaczej ni\u017c \u017car\xf3wki, aby odprowadza\u0107 ciep\u0142o. Istniej\u0105 obawy dotycz\u0105ce niezawodno\u015bci i trwa\u0142o\u015bci \u017car\xf3wek LED, chocia\u017c dost\u0119pne s\u0105 wysokiej jako\u015bci opcje w wy\u017cszej cenie. Wyzwaniem jest integracja \u017car\xf3wek LED z prze\u0142\u0105cznikami \u015bciemniaczy i zapewnienie kompatybilno\u015bci. Migotanie i brak \u017cywych kolor\xf3w w o\u015bwietleniu LED doprowadzi\u0142y do opracowania nowych system\xf3w klasyfikacji i dostrajania \u017car\xf3wek LED. Og\xf3lnie rzecz bior\u0105c, technologia LED ma potencja\u0142, ale wymaga ci\u0105g\u0142ego rozwoju i innowacji.\n",(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35371750",children:"Hacker News Link"}),", ",(0,n.jsx)(e.a,{href:"https://nymag.com/strategist/article/led-light-bulbs-investigation.html",children:"Original Post"}),"."]}),"\n",(0,n.jsx)(e.h2,{id:"ponad-po\u0142owa-nowych-pakiet\xf3w-npm-to-spam",children:"Ponad po\u0142owa nowych pakiet\xf3w NPM to spam"}),"\n",(0,n.jsxs)(e.p,{children:["Ponad po\u0142owa nowych pakiet\xf3w npm to spam, wiele z nich zawiera linki do z\u0142o\u015bliwych stron internetowych lub oferuje fa\u0142szywe gratisy, takie jak Fortnite V-Bucks. Uwa\u017ca si\u0119, \u017ce wzrost ilo\u015bci spamu jest zwi\u0105zany z obozami kodowania, gdzie studenci s\u0105 zach\u0119cani do publikowania pakiet\xf3w, nawet je\u015bli nic nie robi\u0105. Respondenci zaproponowali rozwi\u0105zania takie jak zautomatyzowane procesy testowania i model web-of-trust. Sprawa podkre\u015bla z\u0142o\u017con\u0105 natur\u0119 etyki w bran\u017cy rozwoju oprogramowania oraz napi\u0119cia mi\u0119dzy wolno\u015bci\u0105 s\u0142owa a prawami w\u0142asno\u015bci prywatnej. Badacze bezpiecze\u0144stwa zidentyfikowali obecno\u015b\u0107 pakiet\xf3w spamu w ca\u0142ym rejestrze npm i prowadz\u0105 dalsze dochodzenie.\n",(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35370728",children:"Hacker News Link"}),", ",(0,n.jsx)(e.a,{href:"https://blog.sandworm.dev/one-in-two-new-npm-packages-is-seo-spam-right-now",children:"Original Post"}),"."]}),"\n",(0,n.jsx)(e.h2,{id:"us-proponuje-ustawy-zagra\u017caj\u0105ce-wolno\u015bci-i-prywatno\u015bci-w-technice",children:"US proponuje ustawy zagra\u017caj\u0105ce wolno\u015bci i prywatno\u015bci w technice"}),"\n",(0,n.jsxs)(e.p,{children:['Rz\u0105d USA zaproponowa\u0142 ustaw\u0119, kt\xf3ra da\u0142aby bezprecedensowe uprawnienia do zakazu wszelkich zagranicznych technologii, kt\xf3re uzna za "zagro\u017cenie dla bezpiecze\u0144stwa narodowego", pozostawiaj\u0105c niekt\xf3re z nich twierdz\u0105, \u017ce mo\u017ce to prowadzi\u0107 do Chin-jak uprawnienia cenzury i by\u0107 znacznie szersze ni\u017c pocz\u0105tkowo my\u015blano. Toczy si\u0119 r\xf3wnie\u017c debata na temat zakazu u\u017cywania nale\u017c\u0105cych do Chi\u0144czyk\xf3w aplikacji spo\u0142eczno\u015bciowych - niekt\xf3rzy twierdz\u0105, \u017ce jest to \u015bliski stok w kierunku cenzurowania informacji, podczas gdy inni argumentuj\u0105, \u017ce jest to konieczne, aby uniemo\u017cliwi\u0107 chi\u0144skim firmom kradzie\u017c ameryka\u0144skiej technologii i gromadzenie informacji w celach szpiegowskich. Ustawa RESTRICT jest proponowanym prawem, kt\xf3re mog\u0142oby zosta\u0107 wykorzystane do zakazania TikTok i VPN, a krytycy twierdz\u0105, \u017ce mog\u0142oby to naruszy\u0107 Pierwsz\u0105 Poprawk\u0119. Republika\u0144scy senatorowie zaproponowali r\xf3wnie\u017c zakazanie pracownikom federalnym korzystania z aplikacji medi\xf3w spo\u0142eczno\u015bciowych nale\u017c\u0105cych do chi\u0144skich firm ze wzgl\u0119du na obawy dotycz\u0105ce szpiegostwa i inwigilacji. Niekt\xf3rzy komentatorzy sugeruj\u0105, \u017ce ustawodawstwo sprowadza si\u0119 do protekcjonizmu ze strony rz\u0105du, podczas gdy inni twierdz\u0105, \u017ce wzrost medi\xf3w spo\u0142eczno\u015bciowych szkodzi zdrowiu psychicznemu i przyczynia si\u0119 do manipulacji opini\u0105 publiczn\u0105.\n',(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35369075",children:"Hacker News Link"}),", ",(0,n.jsx)(e.a,{href:"https://www.vice.com/en/article/4a3ddb/restrict-act-insanely-broad-ban-tiktok-vpns",children:"Original Post"}),"."]}),"\n",(0,n.jsx)(e.h2,{id:"open-source-3d-rendering-engine-for-education--integration",children:"Open-Source 3D Rendering Engine for Education & Integration"}),"\n",(0,n.jsxs)(e.p,{children:["Otwarty silnik renderuj\u0105cy 3D StratusGFX zosta\u0142 udost\u0119pniony przez dewelopera dla os\xf3b, kt\xf3re mog\u0105 zintegrowa\u0107 jego kod renderuj\u0105cy z innymi silnikami lub wykorzysta\u0107 go jako \u017ar\xf3d\u0142o edukacyjne. Jego mo\u017cliwo\u015bci obejmuj\u0105 odbicia w czasie rzeczywistym, cienie i pe\u0142ne wsparcie dla cieniowania PBR, ale obecnie obs\u0142uguje on jedynie OpenGL. Jego tw\xf3rca rozwa\u017ca przeportowanie renderera na Vulkan, aby zwi\u0119kszy\u0107 kompatybilno\u015b\u0107 mi\u0119dzyplatformow\u0105. Silnik StratusGFX zosta\u0142 zaprojektowany z my\u015bl\u0105 o maksymalnym realizmie, ale z mo\u017cliwo\u015bci\u0105 kompromisu w przypadku mniej wydajnego sprz\u0119tu, a jego architektura jest dost\u0119pna w serwisie Github dla system\xf3w Windows i Linux. Silnik jest w fazie pre-release/beta-release i nale\u017cy spodziewa\u0107 si\u0119 istotnych b\u0142\u0119d\xf3w i niestabilno\u015bci.\n",(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35370284",children:"Hacker News Link"}),", ",(0,n.jsx)(e.a,{href:"https://github.com/KTStephano/StratusGFX",children:"Original Post"}),"."]}),"\n",(0,n.jsx)(e.h2,{id:"google-zaprzecza-\u017ce-u\u017cywa\u0142-openais-chatgpt-do-szkolenia-barda",children:"Google zaprzecza, \u017ce u\u017cywa\u0142 OpenAI's ChatGPT do szkolenia Barda"}),"\n",(0,n.jsxs)(e.p,{children:["Google zaprzecza wykorzystaniu ChatGPT OpenAI do trenowania Barda, nowego modelu j\u0119zykowego. Pojawi\u0142y si\u0119 obawy dotycz\u0105ce etyki szkolenia jednego du\u017cego modelu j\u0119zykowego z wyj\u015bciem innego komercyjnie kontrolowanego LLM. Warunki korzystania z us\u0142ugi OpenAI zabraniaj\u0105 trenowania konkurencyjnych modeli za pomoc\u0105 wynik\xf3w ML, ale Google nie jest tym zwi\u0105zany. By\u0142y pracownik Google twierdzi\u0142, \u017ce korzysta\u0142 z danych OpenAI, ale Google temu zaprzecza. Materia\u0142 wygenerowany przez AI nie podlega prawom autorskim, a trening na innych danych wyj\u015bciowych modelu jest dozwolony. Niekt\xf3rzy twierdz\u0105, \u017ce kradzie\u017c z ChatGPT mo\u017ce by\u0107 moralnie usprawiedliwiona, poniewa\u017c by\u0142a grupowo pozyskiwana, ale szkolenie modeli na innych danych wygenerowanych przez AI mo\u017ce wymusi\u0107 z\u0142e dane.\n",(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35370915",children:"Hacker News Link"}),", ",(0,n.jsx)(e.a,{href:"https://twitter.com/steventey/status/1641267979399704576",children:"Original Post"}),"."]}),"\n",(0,n.jsx)(e.h2,{id:"twitter-api-neglected-user-dissatisfaction-grows",children:"Twitter API Neglected, User Dissatisfaction Grows"}),"\n",(0,n.jsxs)(e.p,{children:["Twitter API jest podobno pozostawione bez opieki, co prowadzi do problem\xf3w niestabilno\u015bci dla u\u017cytkownik\xf3w. Niekt\xf3rzy u\u017cytkownicy zg\u0142osili, \u017ce czuj\u0105 si\u0119 wyobcowani z serwisu ze wzgl\u0119du na spadek zawarto\u015bci artyku\u0142\xf3w naukowych i zwi\u0119kszony odsetek tre\u015bci pod\u017cegaj\u0105cych lub obra\u017aliwych. Wiele platform medi\xf3w spo\u0142eczno\u015bciowych korzysta z algorytmicznych kana\u0142\xf3w, ale domy\u015blne ustawienia s\u0105 wa\u017cne, poniewa\u017c wp\u0142ywaj\u0105 na zachowanie u\u017cytkownik\xf3w. U\u017cytkownicy Twittera do\u015bwiadczaj\u0105 problem\xf3w, takich jak wewn\u0119trzne b\u0142\u0119dy serwera i trudno\u015bci z dost\u0119pem do strony, co prowadzi niekt\xf3rych do przej\u015bcia na alternatywne platformy, takie jak Mastodon. Ostatnie problemy z niestabilno\u015bci\u0105 Twittera spowodowa\u0142y, \u017ce niekt\xf3rzy u\u017cytkownicy ograniczyli swoje korzystanie z serwisu. Pomimo tych obaw, niekt\xf3rzy uwa\u017caj\u0105, \u017ce wzrost Twittera pod kierownictwem Muska sugeruje, \u017ce platforma nadal b\u0119dzie si\u0119 rozwija\u0107, z lub bez swoich oddanych u\u017cytkownik\xf3w. Decyzja Elona Muska o ograniczeniu dost\u0119pu do API Twittera wywo\u0142uje kontrowersje, z krytykami oskar\u017caj\u0105cymi go o celowe prowadzenie Twittera do ziemi. Twitter API jest teraz skutecznie unmaintained, z tylko jeden pracownik post regularnie na forum Twitter Developers i koncentruje si\u0119 wy\u0142\u0105cznie na API Ads.\n",(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35370152",children:"Hacker News Link"}),", ",(0,n.jsx)(e.a,{href:"https://snarfed.org/the-twitter-api-is-now-effectively-unmaintained",children:"Original Post"}),"."]}),"\n",(0,n.jsx)(e.h2,{id:"san-jose-police-union-director-charged-with-drug-smuggling",children:"San Jose Police Union Director Charged with Drug Smuggling"}),"\n",(0,n.jsxs)(e.p,{children:["Dyrektor wykonawczy Stowarzyszenia Oficer\xf3w Policji w San Jose, Sonia Rosa Segovia, zosta\u0142a oskar\u017cona o przemyt fentanylu do USA i prowadzenie biznesu narkotykowego cz\u0119\u015bciowo z biura. Segovia rzekomo u\u017cywa\u0142a adresu stowarzyszenia do wysy\u0142ania paczek do klient\xf3w i omawia\u0142a sprawy policji ze swoimi dostawcami. Przynajmniej jeden z jej klient\xf3w zmar\u0142 z powodu przedawkowania, a ona sama stoi przed wieloma zarzutami zwi\u0105zanymi z narkotykami. Inne przypadki policjant\xf3w zaanga\u017cowanych w handel narkotykami wywo\u0142a\u0142y pytania o rol\u0119 organ\xf3w \u015bcigania w nielegalnym handlu narkotykami, a niekt\xf3rzy sugeruj\u0105 legalizacj\u0119 jako rozwi\u0105zanie. Rozmowa wok\xf3\u0142 legalizacji narkotyk\xf3w dotyczy tak\u017ce efekt\xf3w zewn\u0119trznych i potrzeby stworzenia system\xf3w wsparcia. Dyrektor wykonawczy zwi\u0105zku zawodowego policji w San Jose, Joanne Southerland, zosta\u0142a oskar\u017cona o przemyt narkotyk\xf3w, podobnie jak Joanne Segovia, pracownica zwi\u0105zku zawodowego policji, kt\xf3ra zosta\u0142a oskar\u017cona o import metamfetaminy do USA. Przypadki te podkre\u015blaj\u0105 potrzeb\u0119 rozwi\u0105za\u0144 w zakresie handlu narkotykami i uzale\u017cnienia, w tym zmian kulturowych i ukierunkowanych dzia\u0142a\u0144 w zakresie egzekwowania prawa.\n",(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35376488",children:"Hacker News Link"}),", ",(0,n.jsx)(e.a,{href:"https://www.washingtonexaminer.com/news/crime/san-jose-police-union-director-smuggle-fentanyl-charge",children:"Original Post"}),"."]})]})}function d(a={}){const{wrapper:e}={...(0,r.R)(),...a.components};return e?(0,n.jsx)(e,{...a,children:(0,n.jsx)(z,{...a})}):z(a)}}}]);